245	--CODE
246	using System;
247	using System.Collections;
248	using UnityEngine;
249	
250	public class CritAfterEvade : HeadgearItem
251	{
252		public static string staticID = "CritAfterEvade";
253	
254		private static GameObject maskPrefab;
255	
256		private NumVarStatMod critMod;
257	
258		private ChaosQuickStopwatch durationStopwatch = new ChaosQuickStopwatch(3f);
259	
260		public CritAfterEvade()
261		{
262			ID = staticID;
263			category = Category.Offense;
264			if (maskPrefab == null)
265			{
266				maskPrefab = ChaosBundle.Get("Assets/Prefabs/Headgear/KitsuneMask.prefab");
267			}
268			headgearPrefab = maskPrefab;
269			critMod = new NumVarStatMod(ID, 1f, 10, VarStatModType.Override);
270		}
271	
272		public override void Activate()
273		{
274			base.Activate();
275			SetEventHandlers(givenStatus: true);
276		}
277	
278		public override void Deactivate()
279		{
280			base.Deactivate();
281			SetEventHandlers(givenStatus: false);
282		}
283	
284		private void SetEventHandlers(bool givenStatus)
285		{
286			if (!(parentEntity == null))
287			{
288				if (givenStatus)
289				{
290					UpdateItemBar(ItemStatusBar.ItemState.Ready);
291				}
292				else
293				{
294					RemoveFromItemBar();
295				}
296				Health health = parentEntity.health;
297				health.evadeEventHandlers = (Health.EvadeEventHandler)Delegate.Remove(health.evadeEventHandlers, new Health.EvadeEventHandler(OnEvadeEvent));
298				if (givenStatus)
299				{
300					Health health2 = parentEntity.health;
301					health2.evadeEventHandlers = (Health.EvadeEventHandler)Delegate.Combine(health2.evadeEventHandlers, new Health.EvadeEventHandler(OnEvadeEvent));
302				}
303			}
304		}
305	
306		private void OnEvadeEvent()
307		{
308			if (durationStopwatch.IsRunning)
309			{
310				durationStopwatch.IsRunning = true;
311			}
312			else if (parentEntity != null)
313			{
314				parentEntity.StartCoroutine(StartCritBuff());
315			}
316		}
317	
318		private IEnumerator StartCritBuff()
319		{
320			if (!durationStopwatch.IsRunning)
321			{
322				UpdateItemBar(ItemStatusBar.ItemState.Active);
323				SetModStatus(givenStatus: true);
324				durationStopwatch.IsRunning = true;
325				while (durationStopwatch.IsRunning)
326				{
327					yield return null;
328				}
329				UpdateItemBar(ItemStatusBar.ItemState.Ready);
330				SetModStatus(givenStatus: false);
331			}
332		}
333	
334		private void SetModStatus(bool givenStatus)
335		{
336			StatManager.ModifyAllStatData(critMod, parentSkillCategory, "criticalHitChance", IgnoreStatusConditional, givenStatus);
337		}
338	}
