{
	string newSkillID = string.Empty;
	switch (newElement)
	{
	case ElementType.Fire:
		newSkillID = "FireChargeFamiliar";
		movement.orbitRadius -= 0.5f;
		spriteOutlineRenderer.color = new Color(1f, 0.2f, 0f, 0.5f);
		spriteOutlineRenderer.material.SetColor("_OutlineColor", new Color(1f, 0.2f, 0f, 0.25f));
		break;
	case ElementType.Air:
		newSkillID = "AirChargeFamiliar";
		spriteOutlineRenderer.color = new Color(0.8f, 0.8f, 0.8f, 0.4f);
		spriteOutlineRenderer.material.SetColor("_OutlineColor", new Color(0.8f, 0.8f, 0.8f, 0.15f));
		break;
	case ElementType.Earth:
		newSkillID = "EarthChargeFamiliar";
		movement.orbitRadius += 0.25f;
		spriteOutlineRenderer.color = new Color(0f, 1f, 0.2f, 0.5f);
		spriteOutlineRenderer.material.SetColor("_OutlineColor", new Color(0f, 1f, 0.2f, 0.25f));
		break;
	case ElementType.Lightning:
		newSkillID = "LightningChargeFamiliar";
		movement.orbitRadius -= 0.25f;
		spriteOutlineRenderer.color = new Color(1f, 0.8f, 0f, 0.4f);
		spriteOutlineRenderer.material.SetColor("_OutlineColor", new Color(1f, 0.8f, 0f, 0.15f));
		break;
	case ElementType.Water:
		newSkillID = "WaterChargeFamiliar";
		movement.orbitRadius += 0.5f;
		spriteOutlineRenderer.color = new Color(0f, 0.8f, 1f, 0.4f);
		spriteOutlineRenderer.material.SetColor("_OutlineColor", new Color(0f, 0.8f, 1f, 0.15f));
		break;
	}
	element = newElement;
	if (parentEntity != null && parentEntity is Player)
	{
