2819				return;
2820			}
2821			speedMod.modValue = 0f;
2822			for (int i = 0; i < parentPlayer.assignedSkills.Length; i++)
2823			{
2824				if (parentPlayer.assignedSkills[i] != null && !parentPlayer.assignedSkills[i].cooldownRef.Ready)
2825				{
