4127		public override void OnTakeDamageActual(AttackInfo givenAtkInfo, Entity givenEnt)
4128		{
4129			if (!(parentPlayer == null) && givenAtkInfo != null && givenAtkInfo.damage > 1 && givenAtkInfo.skillCategory.Contains("Enemy") && !givenAtkInfo.isStatusEffect && (!GameController.pvpOn || givenAtkInfo.skillCategory.Contains("Player")))
4130			{
4131				if (activeTimer.IsRunning)
4132				{
4133					activeTimer.Refresh();
4134				}
4135				else
4136				{
4137					healedAmount = 0;
4138					maxHealAmount = 0;
4139					activeTimer.IsRunning = true;
4140				}
4141				maxHealAmount += Mathf.CeilToInt((float)givenAtkInfo.damage * 0.75f);
4142				if (!isRunningCoroutine)
4143				{
4144					parentPlayer.StartCoroutine(HandleRetributionWindow());
4145				}
4146			}
4147		}
