4149		private IEnumerator HandleRetributionWindow()
4150		{
4151			isRunningCoroutine = true;
4152			UpdateItemBar(ItemStatusBar.ItemState.Active);
4153			Health.globalTakeDamageActualHandlers = (Health.GlobalOnTakeDamageHandler)Delegate.Remove(Health.globalTakeDamageActualHandlers, new Health.GlobalOnTakeDamageHandler(OnHitEnemyEvent));
4154			Health.globalTakeDamageActualHandlers = (Health.GlobalOnTakeDamageHandler)Delegate.Combine(Health.globalTakeDamageActualHandlers, new Health.GlobalOnTakeDamageHandler(OnHitEnemyEvent));
4155			while (activeTimer.IsRunning)
4156			{
4157				yield return null;
4158			}
4159			Health.globalTakeDamageActualHandlers = (Health.GlobalOnTakeDamageHandler)Delegate.Remove(Health.globalTakeDamageActualHandlers, new Health.GlobalOnTakeDamageHandler(OnHitEnemyEvent));
4160			UpdateItemBar(ItemStatusBar.ItemState.Ready);
4161			isRunningCoroutine = false;
4162		}
