4165		{
4166			if (!(attackEntity is Player) || parentPlayer == null || givenAtkInfo.skillCategory != parentPlayer.skillCategory || !activeTimer.IsRunning || parentPlayer.fsm.currentStateName.Contains("Dead") || parentPlayer.health.CurrentHealthValue <= 0)
4167			{
4168				return;
4169			}
4170			if (healedAmount >= maxHealAmount)
4171			{
4172				activeTimer.IsRunning = false;
4173				return;
4174			}
4175			healValue = Mathf.CeilToInt((float)givenAtkInfo.damage * 0.1f);
4176			modHealVal = Mathf.CeilToInt((float)healValue * parentPlayer.health.healModifierStat.CurrentValue);
4177			if (modHealVal + healedAmount > maxHealAmount)
4178			{
4179				healValue = Mathf.CeilToInt((float)(maxHealAmount - healedAmount) / parentPlayer.health.healModifierStat.CurrentValue);
4180			}
4181			parentEntity.health.RestoreHealth(healValue);
4182			healedAmount += Mathf.CeilToInt(modHealVal);
4183		}
4184	}
