4645			parentGroupID = DiscountGroupItem.staticID;
4646		}
4647	
4648		public override void Activate()
4649		{
4650			if (!GroupItemCreated(parentGroupID))
4651			{
4652				StoreItem.globalBuyEventHandlers = (StoreItem.BuyEventHandler)Delegate.Remove(StoreItem.globalBuyEventHandlers, new StoreItem.BuyEventHandler(RestockItem));
4653				StoreItem.globalBuyEventHandlers = (StoreItem.BuyEventHandler)Delegate.Combine(StoreItem.globalBuyEventHandlers, new StoreItem.BuyEventHandler(RestockItem));
4654			}
4655		}
4656	
4657		public override void Deactivate()
