4662		private void RestockItem(Player player, StoreItem storeItem)
4663		{
4664			if (storeItem == null)
4665			{
4666				return;
4667			}
4668			currentSI = null;
4669			if (storeItem is ItemStoreItem)
4670			{
4671				ItemStoreItem itemStoreItem = (ItemStoreItem)storeItem;
4672				if (itemStoreItem.cursedOnly || itemStoreItem.usePlatinumCost || (itemStoreItem.disablePriceMarker && itemStoreItem.Cost == 0))
