4674					return;
4675				}
4676				UnityEngine.Object.Destroy(itemStoreItem.priceMarker.gameObject);
4677				currentSI = Globals.ChaosInst<StoreItem>(ItemMerchant.PrefabDict[ItemMerchant.itemPrefabName], itemStoreItem.transform.parent, itemStoreItem.transform.position);
4678				(currentSI as ItemStoreItem).disableMarkerOffset = itemStoreItem.disableMarkerOffset;
4679			}
4680			else if (storeItem is SkillStoreItem)
4681			{
4682				SkillStoreItem skillStoreItem = (SkillStoreItem)storeItem;
4683				if (skillStoreItem.usePlatinumCost || (skillStoreItem.disablePriceMarker && skillStoreItem.Cost == 0))
4684				{
4685					return;
4686				}
4687				UnityEngine.Object.Destroy(skillStoreItem.priceMarker.gameObject);
4688				currentSI = Globals.ChaosInst<StoreItem>(SkillStoreItem.Prefab, skillStoreItem.transform.parent, skillStoreItem.transform.position);
4689			}
4690			if (currentSI != null)
4691			{
4692				currentSI.GetComponent<SortSpriteLayer>().yValueOffset = storeItem.GetComponent<SortSpriteLayer>().yValueOffset;
4693				currentSI.disablePriceMarker = storeItem.disablePriceMarker;
4694				currentSI.priceMarkerYOffset = storeItem.priceMarkerYOffset;
4695			}
